    /**
     * Method to retrieve the Reservation via ReservationFetchOneSummary
     * @param 	summary ReservationFetchOneSummary 
     * @return 	ReservationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Reservation getReservation( ReservationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ReservationFetchOneSummary arg cannot be null" );
    	
    	Reservation entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Reservation
        	// --------------------------------------
        	CompletableFuture<Reservation> futureEntity = queryGateway.query(new FindReservationQuery( new LoadReservationFilter( summary.getReservationId() ) ), ResponseTypes.instanceOf(Reservation.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Reservation with id " + summary.getReservationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


